@page "/board"
@using sv_06f6eb5dedb846be8b4f0b0cfbbddd26
@inject ITaskService TaskService
@rendermode InteractiveServer

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @_error
        <button class="btn btn-sm btn-outline-danger ms-3" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats Bar -->
    <div class="stats-bar d-flex flex-wrap gap-3 mb-3">
        <span class="badge bg-secondary">Total: @FilteredTasks.Count</span>
        <span class="badge bg-primary">To Do: @GetColumnTasks("To Do").Count</span>
        <span class="badge bg-warning text-dark">In Progress: @GetColumnTasks("In Progress").Count</span>
        <span class="badge bg-success">Done: @GetColumnTasks("Done").Count</span>
        <span class="badge bg-danger">Overdue: @OverdueCount</span>
    </div>

    <!-- Search Bar -->
    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="_searchTerm" @bind:event="oninput" />
    </div>

    <!-- Kanban Columns -->
    <div class="row g-3">
        @foreach (var status in _columns)
        {
            var columnTasks = GetColumnTasks(status);
            <div class="col-md-4">
                <div class="card kanban-column">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@status</strong>
                        <span class="badge bg-secondary rounded-pill">@columnTasks.Count</span>
                    </div>
                    <div class="card-body kanban-body">
                        @foreach (var task in columnTasks)
                        {
                            <div class="card task-card mb-2">
                                <div class="card-body p-2">
                                    <h6 class="card-title mb-1">@task.Title</h6>
                                    <p class="card-text mb-1 text-muted small">@task.Assignee</p>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                                        <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                    </div>
                                    <div class="d-flex justify-content-between mt-2">
                                        @if (GetColumnIndex(status) > 0)
                                        {
                                            var leftStatus = _columns[GetColumnIndex(status) - 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, leftStatus)">
                                                &larr; Move Left
                                            </button>
                                        }
                                        else
                                        {
                                            <span></span>
                                        }
                                        @if (GetColumnIndex(status) < _columns.Length - 1)
                                        {
                                            var rightStatus = _columns[GetColumnIndex(status) + 1];
                                            <button class="btn btn-sm btn-outline-secondary"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task.Id, rightStatus)">
                                                Move Right &rarr;
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        <!-- Add Task Form / Button -->
                        @if (_addingToColumn == status)
                        {
                            <div class="card border-primary mt-2">
                                <div class="card-body p-2">
                                    <input type="text" class="form-control form-control-sm mb-2"
                                           placeholder="Title" @bind="_newTitle" />
                                    <input type="text" class="form-control form-control-sm mb-2"
                                           placeholder="Assignee" @bind="_newAssignee" />
                                    <select class="form-select form-select-sm mb-2" @bind="_newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm mb-2"
                                           @bind="_newDueDate" />
                                    <div class="d-flex gap-2">
                                        <button class="btn btn-sm btn-primary" disabled="@_saving"
                                                @onclick="() => SaveTaskAsync(status)">
                                            @(_saving ? "Saving..." : "Save")
                                        </button>
                                        <button class="btn btn-sm btn-outline-secondary"
                                                disabled="@_saving" @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-sm btn-outline-primary w-100 mt-2"
                                    @onclick="() => StartAdd(status)">
                                + Add Task
                            </button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;

    // Move state
    private int? _movingTaskId;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;

    private List<TaskItem> FilteredTasks =>
        string.IsNullOrWhiteSpace(_searchTerm)
            ? _allTasks
            : _allTasks.Where(t => t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();

    private int OverdueCount =>
        FilteredTasks.Count(t => t.DueDate.Date < DateTime.Today && t.Status != "Done");

    private List<TaskItem> GetColumnTasks(string status) =>
        FilteredTasks.Where(t => t.Status == status).ToList();

    private int GetColumnIndex(string status) => Array.IndexOf(_columns, status);

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task MoveTaskAsync(int taskId, string newStatus)
    {
        _movingTaskId = taskId;

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);

            var idx = _allTasks.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                var old = _allTasks[idx];
                _allTasks[idx] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private void StartAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
    }

    private async Task SaveTaskAsync(string status)
    {
        if (string.IsNullOrWhiteSpace(_newTitle))
            return;

        _saving = true;

        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle.Trim(), _newAssignee.Trim(), _newPriority, _newDueDate);

            // If the task was created with a different status than the target column, move it
            if (created.Status != status)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, status);
                created = created with { Status = status };
            }

            _allTasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _saving = false;
        }
    }
}

.kanban-column {
    min-height: 400px;
}

.kanban-body {
    max-height: 70vh;
    overflow-y: auto;
}

.task-card {
    border-left: 3px solid #6c757d;
}

.stats-bar .badge {
    font-size: 0.9rem;
    padding: 0.5em 0.75em;
}

::deep .priority-high {
    background-color: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background-color: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background-color: #198754;
    color: #fff;
}

